/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n, positions;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    n = lines[0] - 0;
  }

  if (n && lines.length === n + 1) {
    positions = lines.slice(1).map((line) => line.split(" ").map(Number));
    console.log(getResult(n, positions));
    lines.length = 0;
  }
});

function getResult() {
  const tmp = positions.flat(2).sort((a, b) => a - b);

  let l = tmp.at(0);
  let r = tmp.at(-1);
  const eps = 1e-5;

  while (r - l >= eps) {
    const k = (r - l) / 3;
    const ml = l + k;
    const mr = r - k;

    if (getDistance(ml) < getDistance(mr)) {
      r = mr;
    } else {
      l = ml;
    }
  }

  return Math.floor(getDistance(l));
}

function getDistance(t) {
  let dis = 0;
  for (let [l, r] of positions) {
    if (r < t) dis += t - r;
    else if (t < l) dis += l - t;
  }
  return dis;
}

