import java.util.ArrayList;
import java.util.Scanner;

public class Main {
  static double[][] positions;

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    positions = new double[n][2];
    for (int i = 0; i < n; i++) {
      positions[i][0] = sc.nextDouble();
      positions[i][1] = sc.nextDouble();
    }

    System.out.println(getResult());
  }

  public static int getResult() {
    ArrayList<Double> tmp = new ArrayList<>();
    for (double[] pos : positions) {
      tmp.add(pos[0]);
      tmp.add(pos[1]);
    }
    tmp.sort(Double::compareTo);

    double l = tmp.get(0);
    double r = tmp.get(tmp.size() - 1);
    double eps = 1e-5;

    while (r - l >= eps) {
      double k = (r - l) / 3;
      double ml = l + k;
      double mr = r - k;

      if (getDistance(ml) < getDistance(mr)) {
        r = mr;
      } else {
        l = ml;
      }
    }

    return (int) getDistance(l);
  }

  public static double getDistance(double t) {
    double dis = 0;
    for (double[] pos : positions) {
      double l = pos[0];
      double r = pos[1];
      if (r < t) dis += t - r;
      else if (t < l) dis += l - t;
    }
    return dis;
  }
}

