import math

# 输入获取
n = int(input())
positions = [list(map(float, input().split())) for _ in range(n)]


# 算法入口
def getResult():
    tmp = []
    for pos in positions:
        tmp.extend(pos)
    tmp.sort()

    l = tmp[0]
    r = tmp[-1]
    eps = 1e-5

    while r - l >= eps:
        k = (r - l) / 3
        ml = l + k
        mr = r - k

        if getDistance(ml) < getDistance(mr):
            r = mr
        else:
            l = ml

    return int(getDistance(l))


def getDistance(t):
    dis = 0
    for l, r in positions:
        if r < t:
            dis += t - r
        elif t < l:
            dis += l - t
    return dis


